class TableHachage:
    def __init__(self, taille=16):
        self._cases = [[] for _ in range(taille)]
        self._taille = taille

    def _indice(self, cle):
        return hash(cle) % self._taille

    def inserer(self, cle, valeur):
        case = self._cases[self._indice(cle)]
        for i, (c, _) in enumerate(case):
            if c == cle:
                case[i] = (cle, valeur)
                return
        case.append((cle, valeur))

    def rechercher(self, cle):
        for c, v in self._cases[self._indice(cle)]:
            if c == cle:
                return v
        return None

table = TableHachage()
table.inserer("Claire", 17)
table.inserer("Merlin", 14)
table.rechercher("Merlin")

14

Exemple fil rouge : le tri fusion
Le tri fusion (merge sort) divise la liste en deux moitiés, trie chaque moitié récursivement, puis fusionne les deux résultats triés.

def fusionner(gauche, droite):
    resultat = []
    i = j = 0
    while i &lt; len(gauche) and j &lt; len(droite):
        if gauche[i] &lt;= droite[j]:
            resultat.append(gauche[i]); i += 1
        else:
            resultat.append(droite[j]); j += 1
    return resultat + gauche[i:] + droite[j:]

def tri_fusion(liste):
    if len(liste) &lt;= 1:
        return liste
    milieu = len(liste) // 2
    gauche = tri_fusion(liste[:milieu])
    droite = tri_fusion(liste[milieu:])
    return fusionner(gauche, droite)

tri_fusion([5, 3, 8, 2, 9, 1])

[1, 2, 3, 5, 8, 9]

